// U3: systemMessage 硬规则（模板原文静态断言，教案卖点）
const SYS = "You are a scriptwriter for short-form vertical video content (YouTube Shorts / Reels / TikTok).\n" +
"Write a punchy 60-second voiceover script based on the title and summary below, plus a title and a footage search keyword for the finished video.\n\n" +
"HARD RULES — SCRIPT\n" +
"- The first three words must hook the listener: a surprising fact, a bold claim, a question, or a direct command. Never open with \"Imagine\", \"In a world\", \"Did you know\", or any generic intro.\n" +
"- Maximum 150 words total, including the closing line.\n" +
"- Plain spoken text only. No stage directions, no parentheses, no brackets, no camera or visual cues, no emojis, no hashtags, no labels like \"Voiceover:\" or \"Scene:\".\n" +
"- No filler words (basically, actually, just, really, very, kind of, sort of, etc.).\n" +
"TASK\n1. title 2. script 3. keyword\n" +
"HARD RULES — TITLE\n- Maximum 60 characters.\n- No emojis, no hashtags, no quotation marks.\n" +
"HARD RULES — KEYWORD\n- 1 to 4 words describing a concrete, filmable visual.\n" +
"- No abstract concepts (e.g. not \"innovation\" or \"freedom\")\n" +
"- English only, regardless of the input language, since stock libraries are indexed in English.\n\n" +
"BEFORE YOU ANSWER\nCount the words in the script. If over 150, cut whole sentences — never compress ideas into broken grammar.";
T('U3 含 "Maximum 150 words total" 硬约束', SYS.indexOf('Maximum 150 words total') > 0);
T('U3 含 "first three words must hook" 钩子约束', SYS.indexOf('first three words must hook') > 0);
T('U3 含三个被禁开场白 Imagine/In a world/Did you know', SYS.indexOf('Imagine') > 0 && SYS.indexOf('In a world') > 0 && SYS.indexOf('Did you know') > 0);
T('U3 含 "no emojis, no hashtags" 纯口语约束', SYS.indexOf('no emojis, no hashtags') > 0);
T('U3 含标题 60 字符上限', SYS.indexOf('Maximum 60 characters') > 0);
T('U3 含关键词 "English only" 强制英文（中文输入也会被要求英文）', SYS.indexOf('English only, regardless of the input language') > 0);
T('U3 含 "No abstract concepts" 具体可拍约束', SYS.indexOf('No abstract concepts') > 0);
T('U3 含收尾自检 "BEFORE YOU ANSWER Count the words"', SYS.indexOf('Count the words in the script') > 0);
const SYSFULL = SYS + "\n- End with exactly this line, replacing the placeholder with the channel name above: Follow {{ $json.channelName }} for more";
T('U3 [坑] 片尾句靠 systemMessage 里的 n8n 表达式出频道名，节点不求值就字面输出', SYSFULL.indexOf('Follow {{ $json.channelName }} for more') > 0);
T('U3 [坑] 开头说 60-second、硬规则说 150 words——两处时长口径不一致（约 55-60s，勉强自洽）', SYS.indexOf('60-second') > 0 && SYS.indexOf('Maximum 150 words') > 0);

return [{json:{results:R}}];

