// U4: Structured Output Parser 契约（schemaType=manual, 3 字段）
const SCHEMA = {"type":"object","properties":{
  "title":{"type":"string","description":"Short scroll-stopping title for the video, max 60 characters"},
  "script":{"type":"string","description":"Spoken voiceover script, max 150 words, plain text only"},
  "keyword":{"type":"string","description":"1-4 word English keyword for stock footage search"}}};
T('U4 schemaType=manual 手写 JSON Schema', true);
T('U4 三字段齐 title/script/keyword', Object.keys(SCHEMA.properties).length === 3);
T('U4 三字段均为 string', SCHEMA.properties.title.type === 'string' && SCHEMA.properties.script.type === 'string' && SCHEMA.properties.keyword.type === 'string');
T('U4 [坑] schema 无 required 数组 → 模型漏字段 parser 照样放行', SCHEMA.required === undefined);
T('U4 [坑] 无 additionalProperties:false → 模型多吐字段不被拦', SCHEMA.additionalProperties === undefined);
T('U4 [坑] maxLength/字数零校验 → 60 字/150 词全靠模型自觉', SCHEMA.properties.title.maxLength === undefined && SCHEMA.properties.script.maxWords === undefined);
T('U4 约束只写在 description（人读，机器不校验）', SCHEMA.properties.script.description.indexOf('max 150 words') > 0);
T('U4 parser 输出经 LangChain 约定挂到 $json.output.*', true);

return [{json:{results:R}}];

