// U5: Voiceover vars 映射 + undefined 传播（模板：script/keyword/title = $json.output.*, keepOnlySet=true）
// n8n 表达式代理语义：缺失属性返回 undefined 而不抛错（与浏览器 JS 不同）
function voVars(agentJson){ const o = agentJson.output;
  return {script: o ? o.script : undefined, keyword: o ? o.keyword : undefined, title: o ? o.title : undefined}; }
const v1 = voVars({output: {script: 'S', keyword: 'city traffic', title: 'T'}});
T('U5 正常映射三字段', v1.script === 'S' && v1.keyword === 'city traffic' && v1.title === 'T');
T('U5 keepOnlySet → 只留三键（丢 output 原对象）', Object.keys(v1).length === 3);
const v2 = voVars({text: 'model returned raw text'});
T('U5 [坑] parser 失效时 output 缺失 → 三字段全 undefined（n8n 表达式代理不抛错，静默 undefined）', v2.script === undefined && v2.keyword === undefined && v2.title === undefined);
const v3 = voVars({output: {script: 'S'}});
T('U5 [坑] 模型漏 keyword（无 required 兜底）→ keyword=undefined 直达 Pexels', v3.keyword === undefined);
T('U5 [坑] undefined 送 TTS 就是花时间朗读字符串 "undefined"', String(v2.script) === 'undefined');
T('U5 [坑] undefined 进 encodeURIComponent 得字面 "undefined" 查询词', encodeURIComponent(String(v3.keyword)) === 'undefined');

return [{json:{results:R}}];

