// U6: ElevenLabs TTS 请求（模板：url 硬编码 voiceId + bodyParameters text/model_id=eleven_v3）
const VOICE_ID = 'Kq9pDHHIMmJsG9PEqOtv';
function ttsReq(script){
  return {
    url: 'https://api.elevenlabs.io/v1/text-to-speech/' + VOICE_ID,
    method: 'POST',
    sendBody: true, sendHeaders: true,
    bodyParameters: {parameters: [{name:'text', value: script}, {name:'model_id', value:'eleven_v3'}]},
    headerParameters: {parameters: [{name:'Accept', value:'audio/mpeg'}]},
    auth: 'httpHeaderAuth(Elevenlabs API (Axelera))'
  };
}
const q = ttsReq('hello world');
T('U6 url 拼死 voiceId', q.url === 'https://api.elevenlabs.io/v1/text-to-speech/Kq9pDHHIMmJsG9PEqOtv');
T('U6 body 两参 text + model_id', q.bodyParameters.parameters.length === 2);
T('U6 model_id 写死 eleven_v3', q.bodyParameters.parameters[1].value === 'eleven_v3');
T('U6 Accept: audio/mpeg', q.headerParameters.parameters[0].value === 'audio/mpeg');
T('U6 鉴权走 httpHeaderAuth 凭证（xi-api-key）', q.auth.indexOf('httpHeaderAuth') === 0);
T('U6 [坑] 只给 bodyParameters 未指定 json → n8n 默认 form-urlencoded，ElevenLabs 要 JSON（复刻必挂，本厂版换 edge-tts）', q.bodyParameters !== undefined && q.jsonBody === undefined);
T('U6 [坑] 无 voice_settings（stability/similarity）→ 音色随缘', q.bodyParameters.parameters.length === 2);
T('U6 [坑] voiceId 是作者的意大利语女声，换语言/性别只能改 URL', q.url.indexOf('Kq9pDHHIMmJsG9PEqOtv') > 0);

return [{json:{results:R}}];

